//! Parity with the TypeScript engine: every case of `engines/fixtures/text-analysis.json`
//! (generated by `engines/fixtures/text-analysis.ts`) must produce the same bytes.

#![allow(clippy::panic)] // a test harness reports fixture problems by panicking

use serde_json::{Map, Value};
use sipges_analytics_common::js;
use sipges_text_analysis::{
    EngineError, classify_record, public_http_url, text_analysis, text_cosine,
};

type Op = fn(&Map<String, Value>) -> Result<Value, EngineError>;

fn fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/text-analysis.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("fixture field {key} must be a string"))
}

fn op(name: &str) -> Op {
    match name {
        "text_analysis" => text_analysis,
        "classify_record" => classify_record,
        "text_cosine" => text_cosine,
        "public_http_url" => public_http_url,
        other => panic!("unknown fixture op {other}"),
    }
}

#[test]
fn every_case_matches_the_typescript_engine_byte_for_byte() {
    let fixtures = fixtures();
    let cases = fixtures
        .get("cases")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("fixture field cases must be an array"));
    assert!(cases.len() >= 100, "expected the full fixture set");
    let mut failures = Vec::new();
    for case in cases {
        let name = str_of(case, "name");
        let request: Map<String, Value> = serde_json::from_str(str_of(case, "request"))
            .unwrap_or_else(|e| panic!("{name}: request: {e}"));
        match op(str_of(case, "op"))(&request) {
            Ok(value) => {
                let actual = js::stringify(&value);
                let expected = str_of(case, "value");
                if actual != expected {
                    failures.push(format!(
                        "{name}:\n  expected {expected}\n  actual   {actual}"
                    ));
                }
            }
            Err(e) => failures.push(format!("{name}: {e:?}")),
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

fn request(text: &str) -> Map<String, Value> {
    serde_json::from_str(text).unwrap_or_else(|e| panic!("{text}: {e}"))
}

fn code(op: Op, text: &str) -> Option<&'static str> {
    op(&request(text)).err().map(|e| e.code())
}

#[test]
fn rejects_shapes_the_typescript_types_reject() {
    let text_ok = r#""project_id":"P","source_url":"""#;
    for bad in [
        format!(r"{{{text_ok}}}"),
        format!(r#"{{"text":1,{text_ok}}}"#),
        format!(r#"{{"text":null,{text_ok}}}"#),
        r#"{"text":"t","source_url":""}"#.to_owned(),
        r#"{"text":"t","project_id":1,"source_url":""}"#.to_owned(),
        r#"{"text":"t","project_id":"P"}"#.to_owned(),
        r#"{"text":"t","project_id":"P","source_url":null}"#.to_owned(),
        format!(r#"{{"text":"t",{text_ok},"narratives":{{}}}}"#),
        format!(r#"{{"text":"t",{text_ok},"narratives":"x"}}"#),
        format!(r#"{{"text":"t",{text_ok},"narratives":[1]}}"#),
        format!(r#"{{"text":"t",{text_ok},"narratives":[null]}}"#),
        format!(r#"{{"text":"t",{text_ok},"narratives":[[]]}}"#),
    ] {
        assert_eq!(code(text_analysis, &bad), Some("invalid_input"), "{bad}");
    }
    assert_eq!(code(classify_record, "{}"), Some("invalid_input"));
    for bad in [
        r#"{"b":[]}"#,
        r#"{"a":[]}"#,
        r#"{"a":null,"b":[]}"#,
        r#"{"a":[1,"2"],"b":[1,2]}"#,
        r#"{"a":[1,null],"b":[1,2]}"#,
        r#"{"a":{},"b":[]}"#,
    ] {
        assert_eq!(code(text_cosine, bad), Some("invalid_input"), "{bad}");
    }
    for bad in [
        r"{}",
        r#"{"url":null}"#,
        r#"{"url":1}"#,
        r#"{"url":["http://a"]}"#,
    ] {
        assert_eq!(code(public_http_url, bad), Some("invalid_input"), "{bad}");
    }
}

#[test]
fn accepts_any_json_payload_like_classify_record_unknown() {
    for good in [
        r#"{"payload":null}"#,
        r#"{"payload":"agua"}"#,
        r#"{"payload":[1]}"#,
        r#"{"payload":true}"#,
        r#"{"payload":{"a":1}}"#,
    ] {
        assert!(classify_record(&request(good)).is_ok(), "{good}");
    }
}
